package com.gbkhealthcare.billing;
import org.springframework.data.repository.Repository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;import java.util.*;
public interface BillingInvoiceRepository extends Repository<BillingInvoice,Long>{BillingInvoice save(BillingInvoice invoice);Optional<BillingInvoice> findById(Long id);Optional<BillingInvoice> findFirstByPatientVisit_IdAndStatusNot(Long visitId,BillingInvoice.Status status);List<BillingInvoice> findAllByPatientVisit_IdOrderByInvoiceDateDesc(Long visitId);List<BillingInvoice> findAllByOrderByInvoiceDateDesc();@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select i from BillingInvoice i where i.id=:id") Optional<BillingInvoice> findByIdForUpdate(@Param("id") Long id);List<BillingInvoice> findAllByStatusInOrderByInvoiceDateAsc(Collection<BillingInvoice.Status> statuses);}
